css:
.table {
    font-size: inherit;
    margin: 10px 0px;
    background: var(--neutral-white);
    color: #060710;
}
.print-format {
    background-color: white;
    border-radius: 8px;
    max-width: 8.3in;
    min-height: 1.69in;
    margin: auto;
    padding: 13px;
    color: var(--gray-900);
}
.print-format .table-bordered td, .print-format .table-bordered th {
   border: 2px solid var(--invert-neutral);
}
.print-format .table-bordered {
    border: 2px solid var(--invert-neutral);
}
