/*    font-weight: normal;*/
/*    font-size: 14px;*/
/*    color: var(--invert-neutral);*/
/*    margin-bottom: 0;*/
/*}*/
element.style {
    display: block !important;
    order: 0;
    margin-top: 0;
    padding-top: var(--padding-xl);
}
.row {
    margin-left: -10px;
    margin-right: -15px;
    margin-top: -5px;
}
/*element.style {*/
/*    text-align: left;*/
/*    height: 2px;*/
/*}*/
/*.print-format .letter-head {*/
/*    margin-bottom: 30px;*/
/*    height: 2;*/
/*}*/
.customer-address {
    margin-bottom: 5px; /* تقليل المسافة السفلية */
}
.customer-address {
    padding-bottom: 5px; /* تقليل الحشو السفلية */
}
.text-center {
    text-align: center;
    margin-bottom: 0mm;
    color: var(--neutral-white);
}
.print-heading {
    border-bottom: 1px solid #f4f5f6;
    padding-bottom: 5px;
    margin-bottom: 0px;
    text-align: center;
}
.print-format .letter-head {
    margin-bottom: 0px;
}
small, .small {
    font-size: 2%;
}
.print-format label {
    font-weight: normal;
    font-size: 13px;
    color: #060710;
    margin-bottom: 0;
}

.col-xs-5 {
    width: 20.66666667%;
}

.col-xs-7 {
    width: 60.33333333%;
}
.print-format td, .print-format th {
    padding: 1px !important;
}
th {
    text-align: center;
}
.table {
    width: 100%;
    max-width: 100%;
    margin-bottom: 0;
}

.print-format th {
    background-color: transparent !important;
    border-bottom: 1px solid !important;
    border-top: none !important;
}
.print-format .ql-editor {
    padding-left: 0px;
    padding-right: 0px;
}

.print-format table {
    margin-bottom: 0px;
    }
.print-format .table-data tr:last-child { 
    border-bottom: 1px solid !important;
}

.print-format .table-inner tr:last-child {
    border-bottom:none !important;
}
.print-format .table-inner {
    margin: 0px 0px;
}

.print-format .table-data ul li { 
    color:#787878 !important;
}

.no-top-border {
    border-top:none !important;
}

.table-inner td {
    padding-left: 0px !important;    
    padding-top: 1px !important;
    padding-bottom: 1px !important;
    color:#787878 !important;
}

.total {
    background-color: lightgrey !important;
    padding-top: 4px !important;
    padding-bottom: 4px !important;
}

